const keywords = $json.keywords.split(',').map(k => k.trim());

return keywords.map(keyword => {
  return {
    json: {
      keyword,
      rssUrl: `https://news.google.com/rss/search?q=${encodeURIComponent(keyword)}&hl=en-US&gl=US&ceid=US:en`
    }
  };
});

const inputItems = $input.all();

if (inputItems.length === 0) {
  return [
    {
      json: {
        digest: `News Monitor Digest

Generated At: ${new Date().toLocaleString()}

No important news found in this run.`,
        itemCount: 0
      }
    }
  ];
}

const rows = inputItems.map((item, index) => {
  const j = item.json;
  const a = j.aiAnalysis || {};

  return `${index + 1}. ${j.title || 'No title'}
Keyword: ${j.keyword || 'N/A'}
Source: ${j.source || 'Unknown'}
Published: ${j.publishedAt || 'N/A'}
Sentiment: ${a.sentiment || 'N/A'}
Importance: ${a.importance || 'N/A'} (${a.score || 0}/10)
Summary: ${a.summary || 'No summary'}
Reason: ${a.reason || 'No reason'}
URL: ${j.url || 'N/A'}`;
});

const digest = `News Monitor Digest

Generated At: ${new Date().toLocaleString()}

Total Important Articles: ${inputItems.length}

${rows.join('\n\n')}`;

return [
  {
    json: {
      digest,
      itemCount: inputItems.length
    }
  }
];

const output = [];

for (const item of items) {
  const xml = item.json.data || '';
  const keyword = item.json.keyword || item.json.searchKeyword || item.json.brand || '';

  if (!xml || !xml.includes('<item>')) {
    continue;
  }

  const getTagValue = (block, tag) => {
    const regex = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
    const match = block.match(regex);
    return match ? match[1].trim() : '';
  };

  const decodeHtml = (text = '') => {
    return text
      .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&nbsp;/g, ' ');
  };

  const stripHtml = (text = '') => {
    return decodeHtml(text)
      .replace(/<a [^>]*>/gi, '')
      .replace(/<\/a>/gi, '')
      .replace(/<font [^>]*>/gi, '')
      .replace(/<\/font>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  };

  const itemBlocks = xml.match(/<item>([\s\S]*?)<\/item>/gi) || [];

  for (const block of itemBlocks) {
    const title = stripHtml(getTagValue(block, 'title'));
    const url = decodeHtml(getTagValue(block, 'link'));
    const publishedAt = stripHtml(getTagValue(block, 'pubDate'));
    const descriptionRaw = getTagValue(block, 'description');
    const description = stripHtml(descriptionRaw);

    let source = '';
    const sourceTag = block.match(/<source[^>]*>([\s\S]*?)<\/source>/i);
    if (sourceTag) {
      source = stripHtml(sourceTag[1]);
    }

    if (!source && descriptionRaw) {
      const sourceFromDesc = descriptionRaw.match(/<font[^>]*>([\s\S]*?)<\/font>/i);
      if (sourceFromDesc) {
        source = stripHtml(sourceFromDesc[1]);
      }
    }

    output.push({
      json: {
        keyword: keyword || '',
        title: title || '',
        url: url || '',
        source: source || 'Unknown',
        publishedAt: publishedAt || '',
        description: description || ''
      }
    });
  }
}

return output;

const results = [];

for (const item of $input.all()) {
  try {
    // Get the text content from the AI response structure
    const text = item.json.content?.parts?.[0]?.text || '';

    if (!text) {
      console.log('No text found in item');
      continue;
    }

    // Extract JSON from markdown code block (remove ```json and ```)
    let jsonString = text
      .replace(/^```json\s*/i, '')
      .replace(/```$/i, '')
      .replace(/\\n/g, '\n')  // Fix escaped newlines
      .replace(/\\"/g, '"')    // Fix escaped quotes
      .trim();

    // Parse the JSON
    const parsedJson = JSON.parse(jsonString);

    // Create clean output with original fields + parsed data
    results.push({
      json: {
        ...item.json,  // Keep original fields (title, url, keyword, etc.)
        aiAnalysis: {
          summary: parsedJson.summary || '',
          sentiment: parsedJson.sentiment || '',
          importance: parsedJson.importance || '',
          score: parsedJson.score || 0,
          reason: parsedJson.reason || '',
          source: parsedJson.source || ''
        }
      }
    });

  } catch (error) {
    console.log(`Error parsing item: ${error.message}`);
    console.log('Raw text:', item.json.content?.parts?.[0]?.text);

    // Add failed item with error info
    results.push({
      json: {
        ...item.json,
        aiAnalysis: {
          error: `Failed to parse JSON: ${error.message}`,
          rawText: item.json.content?.parts?.[0]?.text
        }
      }
    });
  }
}

return results;

const freshItems = $input.all();
const oldItems = $('Read Existing News Log').all();

const existing = new Set();
for (const row of oldItems) {
  const url = (row.json.url || '').trim().toLowerCase();
  const hash = (row.json.hash || '').trim().toLowerCase();
  if (url) existing.add(url);
  if (hash) existing.add(hash);
}

function makeHash(item) {
  const base = `${item.title}|${item.url}`.toLowerCase().trim();
  let hash = 0;
  for (let i = 0; i < base.length; i++) {
    hash = ((hash << 5) - hash) + base.charCodeAt(i);
    hash |= 0;
  }
  return String(hash);
}

const results = [];
for (const item of freshItems) {
  const url = (item.json.url || '').trim().toLowerCase();
  const hash = makeHash(item.json);
  if (!existing.has(url) && !existing.has(hash)) {
    results.push({
      json: {
        ...item.json,
        hash,
        processedAt: new Date().toISOString()
      }
    });
  }
}
return results;
